<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');require_once __DIR__.'/conexion.php';
try{if(($_SERVER['REQUEST_METHOD']??'')!=='DELETE')throw new RuntimeException('Método no permitido.');$data=json_decode((string)file_get_contents('php://input'),true)?:[];$dni=trim((string)($data['dni']??''));$tipo=mb_strtoupper(trim((string)($data['tipo']??'')),'UTF-8');if(!preg_match('/^\d{8}$/',$dni)||!in_array($tipo,['INGRESO','REINGRESO'],true))throw new InvalidArgumentException('Solicitud inválida.');$db=obtenerConexion();$p=$db->prepare('SELECT codmod FROM alfa1 WHERE TRIM(le)=:dni LIMIT 1');$p->execute(['dni'=>$dni]);$codmod=(string)($p->fetchColumn()?:'');if($codmod==='')throw new RuntimeException('Servidor no encontrado.');if($tipo==='INGRESO'){$check=$db->prepare('SELECT Res_Ing FROM alfa3 WHERE TRIM(LE)=:dni OR CAST(codmod AS UNSIGNED)=CAST(:codmod AS UNSIGNED) LIMIT 1');$sql="UPDATE alfa3 SET Res_Ing='',Fec_Res=NULL,OK_INGRESO=0 WHERE TRIM(LE)=:dni OR CAST(codmod AS UNSIGNED)=CAST(:codmod AS UNSIGNED) LIMIT 1";}else{$check=$db->prepare('SELECT REINGRESO_RESOLUCION FROM alfa3 WHERE TRIM(LE)=:dni OR CAST(codmod AS UNSIGNED)=CAST(:codmod AS UNSIGNED) LIMIT 1');$sql="UPDATE alfa3 SET REINGRESO_RESOLUCION='',REINGRESO_RESOLUCION_FECHA=NULL,REINGRESO_FECHA=NULL,OK_REINGRESO=0 WHERE TRIM(LE)=:dni OR CAST(codmod AS UNSIGNED)=CAST(:codmod AS UNSIGNED) LIMIT 1";}$params=['dni'=>$dni,'codmod'=>$codmod];$check->execute($params);if($check->fetchColumn()===false)throw new RuntimeException('Registro de ingreso no encontrado.');$db->prepare($sql)->execute($params);echo json_encode(['ok'=>true,'mensaje'=>'Registro de ingreso eliminado correctamente.'],JSON_UNESCAPED_UNICODE);
